#!/usr/bin/env node
// Renders .ai-architecture/phase-3-skills/SKILL_CATALOG.md from SKILL_CATALOG.json (the JSON is
// generated by build-skill-catalog.ts from backend/src/skills/catalog.ts).
// Usage (repo root): node scripts/ai-architecture/render-skill-catalog.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const DIR = '.ai-architecture/phase-3-skills';
const catalog = JSON.parse(readFileSync(`${DIR}/SKILL_CATALOG.json`, 'utf8'));
const esc = (v) =>
  String(v ?? '')
    .replace(/\|/g, '\\|')
    .replace(/\n/g, ' ');
const { totals } = catalog;

const lines = [
  '# Skill Catalog — Phase 3',
  '',
  '> Generated from `SKILL_CATALOG.json` (source of record `backend/src/skills/catalog.ts`) by',
  '> `scripts/ai-architecture/build-skill-catalog.ts` + `render-skill-catalog.mjs`. Do not edit by hand.',
  '',
  `Totals: ${Object.entries(totals)
    .map(([k, v]) => `${k} ${v}`)
    .join(' · ')} · confirmation policy v${catalog.confirmation_policy_version}`,
  '',
  '| skill_id | nome | categoria | tipo | conferma | tool richiesti | tool opzionali | ruoli previsti | stato | evidenze |',
  '|---|---|---|---|---|---|---|---|---|---|',
  ...catalog.skills.map(
    (s) =>
      `| \`${s.skill_id}\` | ${esc(s.name)} | ${s.category} | ${s.kind} | ${s.confirmation} | ${esc(s.required_capabilities.join(', '))} | ${esc(s.optional_capabilities.join(', ') || '—')} | ${esc(s.intended_roles.join(', '))} | ${s.implementation_status} | ${s.test_evidence.length} |`,
  ),
  '',
  '## Dettaglio',
  '',
  ...catalog.skills.flatMap((s) => [
    `### \`${s.skill_id}\` — ${s.name}`,
    '',
    s.description,
    '',
    `- Input/contesto: ${s.input_context.join(', ') || '—'} · Output: ${s.output}`,
    `- Workflow: ${s.workflow_steps.join(' → ')}`,
    `- Ambiguità: ${s.ambiguity_handling}`,
    `- Errori: ${s.failure_handling}`,
    `- Audit: ${s.audit} · Sensibilità: ${s.sensitivity}`,
    ...(s.customer_validation
      ? [`- **Da validare con il cliente:** ${s.customer_validation}`]
      : []),
    `- Evidenze: ${s.test_evidence.join('; ') || 'nessuna (non eseguibile dall’assistente)'}`,
    '',
  ]),
];
writeFileSync(`${DIR}/SKILL_CATALOG.md`, lines.join('\n'));
console.log(`SKILL_CATALOG.md written (${catalog.skills.length} skills)`);
